import io
import os
import wave

import discord
from discord import app_commands
from discord.ext import commands, voice_recv
from dotenv import load_dotenv

load_dotenv()

intents = discord.Intents.default()
bot = commands.Bot(command_prefix="!", intents=intents)

# guild_id -> (VoiceRecvClient, UserBufferSink)
sessions = {}


class UserBufferSink(voice_recv.AudioSink):
	"""Keeps raw PCM per user in RAM. No silence padding yet (spike only)."""

	def __init__(self):
		super().__init__()
		self.buffers = {}

	def wants_opus(self) -> bool:
		# False = we get decoded 48kHz 16-bit stereo PCM
		return False

	def write(self, user, data: voice_recv.VoiceData):
		if user is None:
			return
		if user.id not in self.buffers:
			print(f"First packet from {user} ({len(data.pcm)} bytes)")
			self.buffers[user.id] = bytearray()
		self.buffers[user.id].extend(data.pcm)

	def cleanup(self):
		pass


def pcm_to_wav(pcm: bytes) -> io.BytesIO:
	out = io.BytesIO()
	with wave.open(out, "wb") as w:
		w.setnchannels(2)
		w.setsampwidth(2)
		w.setframerate(48000)
		w.writeframes(pcm)
	out.seek(0)
	return out


@bot.event
async def setup_hook():
	await bot.tree.sync()


@bot.event
async def on_ready():
	print(f"Logged in as {bot.user}")


@bot.tree.command(name="start", description="Join your voice channel and start recording")
async def start(interaction: discord.Interaction):
	voice = interaction.user.voice
	if not voice:
		return await interaction.response.send_message("Join a voice channel first!", ephemeral=True)

	if interaction.guild.id in sessions:
		return await interaction.response.send_message("Already recording here.", ephemeral=True)

	await interaction.response.defer()

	vc = await voice.channel.connect(cls=voice_recv.VoiceRecvClient)
	sink = UserBufferSink()
	vc.listen(sink)
	sessions[interaction.guild.id] = (vc, sink)

	await interaction.followup.send("Recording! Say something.")


@bot.tree.command(name="stop", description="Stop recording, post the audio, and leave")
async def stop(interaction: discord.Interaction):
	session = sessions.pop(interaction.guild.id, None)
	if not session:
		return await interaction.response.send_message("I'm not recording here.", ephemeral=True)

	await interaction.response.defer()

	vc, sink = session
	vc.stop_listening()
	await vc.disconnect()

	if not sink.buffers:
		return await interaction.followup.send("Recorded nothing. (No audio arrived - DAVE decryption probably failed.)")

	files = []
	report = []
	for user_id, pcm in sink.buffers.items():
		seconds = len(pcm) / (48000 * 2 * 2)
		report.append(f"<@{user_id}>: {seconds:.1f}s")
		files.append(discord.File(pcm_to_wav(bytes(pcm)), f"{user_id}.wav"))

	await interaction.followup.send("Recorded:\n" + "\n".join(report), files=files)


bot.run(os.environ["DISCORD_TOKEN"])